CREATE TABLE IF NOT EXISTS `song_submissions` (`id` INT NOT NULL AUTO_INCREMENT, `userId` INT NOT NULL, `seasonId` INT NULL, `title` VARCHAR(200) NOT NULL, `artist` VARCHAR(200) NULL, `audioUrl` VARCHAR(500) NOT NULL, `description` TEXT NULL, `voteCount` INT NOT NULL DEFAULT 0, `status` VARCHAR(20) NOT NULL DEFAULT 'pending', `submittedAt` TIMESTAMP NOT NULL DEFAULT CURRENT_TIMESTAMP, PRIMARY KEY (`id`), INDEX `idx_song_submissions_season` (`seasonId`), INDEX `idx_song_submissions_user_season` (`userId`, `seasonId`), INDEX `idx_song_submissions_status` (`status`));

CREATE TABLE IF NOT EXISTS `song_submission_votes` (`id` INT NOT NULL AUTO_INCREMENT, `songSubmissionId` INT NOT NULL, `userId` INT NOT NULL, `seasonId` INT NULL, `createdAt` TIMESTAMP NOT NULL DEFAULT CURRENT_TIMESTAMP, PRIMARY KEY (`id`), UNIQUE KEY `uniq_user_season_vote` (`userId`, `seasonId`), INDEX `idx_song_votes_submission` (`songSubmissionId`));

INSERT INTO `game_variables` (`category`, `subcategory`, `key`, `displayName`, `description`, `value`, `valueType`, `defaultValue`, `isActive`) SELECT 'rewards', 'hymns', 'hymnSubmissionWinnerReward', 'Hymn Submission Winner Reward', 'ReGen tokens awarded to the player whose song wins the seasonal hymn community vote', 3333, 'integer', 3333, 1 WHERE NOT EXISTS (SELECT 1 FROM `game_variables` WHERE `key` = 'hymnSubmissionWinnerReward');
